"""Dependency-free portfolio generator. Run from any working directory."""
from pathlib import Path
import json, html, shutil
ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'docs'
PROJECTS = json.loads((ROOT / 'portfolio/projects.json').read_text(encoding='utf-8'))

def e(value):
    return html.escape(str(value), quote=True)

def shell(title, description, body, prefix=''):
    return f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{e(description)}"><meta name="theme-color" content="#243f36"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(description)}"><meta property="og:type" content="website"><title>{e(title)}</title><link rel="icon" href="{prefix}assets/mark.svg" type="image/svg+xml"><link rel="stylesheet" href="{prefix}assets/style.css"><script src="{prefix}assets/site.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header><a class="wordmark" href="{prefix}index.html" aria-label="Tiffany Legg home">tl<span> / </span>Tiffany Legg</a><nav aria-label="Main navigation"><a href="{prefix}index.html#work">Selected work</a><a href="{prefix}index.html#about">Experience</a><a href="{prefix}index.html#contact">Let’s connect ↗</a></nav></header>{body}<footer><span>Tiffany Legg / Operations × Technology</span><span>Parma Heights, Ohio · © 2026</span><a href="https://github.com/Ladybugverse/personal-website">Portfolio source ↗</a></footer></body></html>'

def graphic(p):
    labels = {'mow-magic': ['Customer intake', 'Lead record', 'Service planning', 'Field coordination'], 'everfold': ['Template definition', 'Pinned version', 'Invitation blocks', 'Recipient experience'], 'runhouse': ['Project package', 'Optional add-ons', 'Maintenance', 'Estimate breakdown'], 'design-system': ['Brand tokens', 'Presentational layer', 'Version contract', 'Application reuse']}[p['slug']]
    return '<div class="system-map ' + p['slug'] + '" aria-label="Conceptual project structure"><div class="map-top"><span>FIELD NOTES / ' + e(p['slug'].upper()) + '</span><span>↗</span></div><div class="map-mark">' + {'mow-magic': 'M / M', 'everfold': 'e.', 'runhouse': 'R / H', 'design-system': 'Aa'}[p['slug']] + '</div><div class="map-nodes">' + ''.join((f'<span><i>{i:02}</i>{e(label)}</span>' for i, label in enumerate(labels, 1))) + '</div><small>Conceptual structure · not an application screenshot</small></div>'

def evidence(p):
    items = []
    for label, repo, path, ref, private in p['evidence']:
        url = path if repo == 'notion' else f'https://github.com/Ladybugverse/{repo}/blob/{ref}/{path}'
        items.append(f'''<li><a href="{e(url)}">{e(label)} ↗</a><small>{('Access restricted · available to authorized reviewers' if private else 'Public source')}</small></li>''')
    return '<ul class="evidence">' + ''.join(items) + '</ul>'
OUT.mkdir(exist_ok=True)
if (OUT / 'work').exists():
    shutil.rmtree(OUT / 'work')
for p in PROJECTS:
    dest = OUT / 'work' / p['slug']
    dest.mkdir(parents=True, exist_ok=True)
    sections = ''.join((f'<section class="prose"><h2>{e(title)}</h2><p>{e(text)}</p></section>' for title, text in p['sections']))
    body = f"""<main id="main"><div class="case-hero"><a class="back" href="../../index.html#work">← All selected work</a><p class="eyebrow">{e(p['category'])}</p><h1>{e(p['name'])}<span class="period">.</span></h1><p class="lead">{e(p['summary'])}</p><span class="status">{e(p['status'])} · Deployment unverified</span></div><div class="case-grid"><aside><h2 class="eyebrow">At a glance</h2><h3>Role & contribution</h3><p>{e(p['role'])}</p><h3>Technology in the source</h3><p>{e(p['tech'])}</p><h3>Business problem</h3><p>{e(p['challenge'])}</p><p class="micro">Evidence reviewed October 14, 2026. Source code establishes implementation, not production use.</p></aside><article>{graphic(p)}{sections}<section class="boundary"><p class="eyebrow">Implementation status</p><h2>What still needs verification</h2><p>{e(p['boundary'])}</p></section><section class="prose"><h2>Implementation evidence</h2><p>Private project links require repository access. No private source code, customer records, or credentials are reproduced here.</p>{evidence(p)}</section><a class="button" href="../../index.html#contact">Discuss this work ↗</a></article></div></main>"""
    (dest / 'index.html').write_text(shell(p['name'] + ' — Tiffany Legg', p['summary'], body, '../../'), encoding='utf-8')
cards = ''.join((f'''<article class="project" data-tags="{' '.join(p['tags'])}"><a class="project-art" href="work/{p['slug']}/index.html" aria-label="Read {e(p['name'])} case study">{graphic(p)}</a><div class="project-info"><span class="eyebrow">{i:02} / {e(p['category'])}</span><h3><a href="work/{p['slug']}/index.html">{e(p['name'])} <span>↗</span></a></h3><p>{e(p['summary'])}</p><p class="micro">{e(p['tech'])}</p><span class="status">{e(p['status'])}</span></div></article>''' for i, p in enumerate(PROJECTS, 1)))
body = '<main id="main"><section class="hero"><div><p class="eyebrow">Operations leadership / Business systems / Creative technology</p><h1>I connect the<br>business to<br><em>the build.</em></h1><p class="lead">I’m Tiffany Legg. I turn operational needs into thoughtful workflows, useful applications, and a consistent customer experience.</p><div class="actions"><a class="button" href="#work">Explore selected work <span>↘</span></a><a class="text-link" href="#about">The experience behind it →</a></div></div><aside class="hero-note"><span class="note-number">01—04</span><p class="eyebrow">A portfolio of connected work</p><div class="orbit"><span>BUSINESS<br>NEEDS</span><b>×</b><span>USEFUL<br>SYSTEMS</span></div><p>From the first customer touchpoint to the records and processes behind the work.</p><div class="note-line"><span>Based in Northeast Ohio</span><span>↗</span></div></aside></section><section class="intro-band"><p>Operational perspective.<br><em>Technical follow-through.</em></p><p>Current Capital One IRA operations experience, combined with cross-functional leadership at Mow Magic across business systems, web development, brand, marketing, and process documentation.</p></section><section id="work" class="work"><div class="section-heading"><div><p class="eyebrow">01 / Selected work</p><h2>Systems with a purpose.</h2></div><p>Business context, implementation decisions,<br>and evidence you can examine.</p></div><div class="filters" hidden role="group" aria-label="Filter projects"><button aria-pressed="true" data-filter="all">All work</button><button aria-pressed="false" data-filter="operations">Operations</button><button aria-pressed="false" data-filter="systems">Business systems</button><button aria-pressed="false" data-filter="design">Brand & experience</button></div><p id="filter-result" class="sr-only" aria-live="polite"></p><div class="projects">' + cards + '</div><div class="evidence-note"><strong>Clear evidence. Honest scope.</strong><p>Projects are labeled by what has been inspected: source implementations, development work, and prototypes. No live deployment or measured business result is implied. The diagrams are conceptual exhibits, not screenshots.</p></div></section><section id="about" class="about"><div><p class="eyebrow">02 / Experience & capabilities</p><h2>The person behind<br><em>the systems.</em></h2><p class="lead">I work across the details that connect an organization: people, processes, records, interfaces, and brand.</p><p>My Mow Magic responsibilities extend from operational planning and SOPs to website management, CRM requirements, custom applications, content, promotions, and visual identity. I lead development by connecting business requirements to practical implementation.</p><p>I use the portfolio to make that work assessable, without claiming sole authorship of every component.</p></div><div class="experience"><section><span class="eyebrow">Current / Financial operations</span><h3>Capital One</h3><p>IRA / retirement account operations. A foundation in structured account work and careful operational recordkeeping.</p></section><section><span class="eyebrow">Cross-functional leadership</span><h3>Mow Magic Landscaping & Snow Removal LLC</h3><p>COO & Director of Operations, Corporate & Environmental Compliance — user-confirmed role. Operations, business systems, web development, brand, and marketing.</p></section><section><span class="eyebrow">Capabilities demonstrated in the work</span><ul class="skills"><li>Workflow & requirements design</li><li>CRM & customer records</li><li>SOPs & process documentation</li><li>Web & application delivery</li><li>Brand systems & content</li><li>Reusable UI & structured data</li></ul><p class="micro">Project stacks reflect inspected repositories, rather than certifications or a claim of equal proficiency in every technology.</p></section></div></section><section class="method"><p class="eyebrow">03 / How I approach the work</p><div class="method-grid"><div><span>01</span><h3>Understand the operation.</h3><p>Start with the people, decisions, records, and handoffs the system needs to support.</p></div><div><span>02</span><h3>Make the structure clear.</h3><p>Define reusable data, workflows, and interface patterns around those needs.</p></div><div><span>03</span><h3>Show the evidence.</h3><p>Explain the choices, inspect the implementation, and separate what exists from what still needs validation.</p></div></div></section><section id="contact" class="contact"><p class="eyebrow">04 / Let’s connect</p><h2>Bring the business<br>and the build <em>together.</em></h2><p>I’m interested in operations leadership, business systems, CRM, automation, and technology opportunities.</p><div class="actions"><a class="button" href="mailto:tifflegg93@gmail.com">Email me ↗</a><a class="text-link" href="https://github.com/Ladybugverse">Find me on GitHub ↗</a></div><p class="micro">For employer inquiries: <a href="mailto:tifflegg93@gmail.com">tifflegg93@gmail.com</a></p></section></main>'
(OUT / 'index.html').write_text(shell('Tiffany Legg — Operations & Business Systems', 'Operations leadership, business systems, web development, and brand work by Tiffany Legg. Explore evidence-backed project case studies.', body), encoding='utf-8')
(OUT / '.nojekyll').touch()
(OUT / '404.html').write_text(shell('Page not found — Tiffany Legg', 'Page not found', '<main id="main" class="case-hero"><h1>Let’s get you back.</h1><p>This page could not be found.</p><a href="/personal-website/">Return to the portfolio →</a></main>', prefix='/personal-website/'), encoding='utf-8')
print(f'Built {len(PROJECTS)} case studies and home into docs/')
